/* OFFLINE DESIGN REFERENCE. Fictional records only. No fetch, tokens, real geolocation or payments. */
const {scenes,products,icons,assets}=REFERENCE;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ic=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const pic=(name,cls='',alt='')=>`<img class="${cls}" src="${assets[name]}" alt="${esc(alt)}">`;
const art=(id,cls='')=>pic(`product-${id}.svg`,cls,'Illustrative '+(products.find(p=>p.id===id)?.name||id));
const btn=(label,act,kind='',extra='')=>`<button class="btn ${kind}" data-act="${act}" ${extra}>${label}</button>`;
const ib=(name,act,label=name)=>`<button class="icon-btn" data-act="${act}" aria-label="${esc(label)}">${ic(name)}</button>`;
const link=(label,act)=>`<button class="link" data-act="${act}">${label}</button>`;
const badge=(text,kind='')=>`<span class="pill ${kind}">${text}</span>`;
const notice=(text,kind='',name='info')=>`<div class="notice ${kind}">${ic(name)}<div>${text}</div></div>`;
const money=p=>'Rs '+(p/100).toLocaleString('en-PK',{minimumFractionDigits:p%100?2:0,maximumFractionDigits:2});
const init=()=>({view:'home',cart:{},member:false,located:false,selected:'milk',shop:'grocer',offer:'grocer',category:'All',query:'',filter:'All',modal:null,history:[],address:{name:'',phone:'',fullAddress:'',city:'',instructions:''},phone:'',code:'',authReason:'checkout',rating:0,orderPlaced:false,orderSnapshot:null,mergeProblem:false});
let S=init(),toastTimer,previousFocus;
let theme='system';try{theme=localStorage.getItem('sb.customer.design.theme')||'system'}catch{}if(!['light','dark','system'].includes(theme))theme='system';
const media=matchMedia('(prefers-color-scheme:dark)');
function isDark(){return theme==='dark'||theme==='system'&&media.matches}
function applyTheme(t=theme){theme=t;document.documentElement.dataset.theme=isDark()?'dark':'light';try{localStorage.setItem('sb.customer.design.theme',theme)}catch{}document.querySelectorAll('[data-theme-choice]').forEach(b=>{b.classList.toggle('selected',b.dataset.themeChoice===theme);b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme))});document.querySelectorAll('[data-logo]').forEach(el=>el.src=assets['sirfbazar-horizontal-no-slogan-'+(isDark()?'dark':'light')+'.png']);document.querySelectorAll('[data-slogan]').forEach(el=>el.src=assets['sirfbazar-slogan-urdu-'+(isDark()?'dark':'light')+'.png'])}
media.addEventListener('change',()=>{if(theme==='system')applyTheme()});
const totalQty=()=>Object.values(S.cart).reduce((a,b)=>a+b,0);
const cartProducts=()=>products.filter(p=>S.cart[p.id]>0);
function quote(){let items=cartProducts(),sub=items.reduce((a,p)=>a+p.price*S.cart[p.id],0),groups=[...new Set(items.map(p=>p.merchantId))];return{sub,delivery:groups.length*6000,service:items.length?2000:0,total:sub+groups.length*6000+(items.length?2000:0),groups}}
function seedCart(multi=false){S.cart={milk:1,bread:1,eggs:1};if(multi)S.cart.banana=1}
function seedAddress(){S.address={name:'Example customer',phone:'',fullAddress:'House 12, Example Street, Gulberg',city:'Lahore',instructions:'Please ring the bell.'};S.located=true}
const section=(name,action,label='See all')=>`<div class="section-head"><h2>${name}</h2>${action?link(label,action):''}</div>`;
const field=(label,key,value='',placeholder='',type='text')=>`<label class="field"><span>${label}</span><input class="input" type="${type}" data-field="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}"></label>`;
const list=(icon,title,desc,action,right='')=>`<button class="list-item" data-act="${action}">${ic(icon)}<span class="grow"><b>${title}</b>${desc?`<p>${desc}</p>`:''}</span>${right||ic('chevron','chev')}</button>`;
function stepper(id){return `<div class="stepper"><button data-act="less:${id}" aria-label="Remove one ${esc(products.find(p=>p.id===id)?.name)}">${ic('minus')}</button><b>${S.cart[id]}</b><button data-act="add:${id}" aria-label="Add one ${esc(products.find(p=>p.id===id)?.name)}">${ic('plus')}</button></div>`}
function productCard(p,catalog=false){return `<article class="product-card"><button class="product-art" data-act="product:${p.id}" aria-label="View ${esc(p.name)}">${art(p.id)}</button><button class="product-name" data-act="product:${p.id}">${p.name}</button><p class="product-unit">${p.unit}</p><p class="seller-line">${catalog?'Choose a local seller':p.shop}</p>${catalog?btn('Check availability','product:'+p.id,'soft full','style="font-size:11px;padding:8px;min-height:39px"'):`<div class="product-footer ${S.cart[p.id]?'has-qty':''}"><b class="price">${money(p.price)}</b>${S.cart[p.id]?stepper(p.id):`<button class="add-btn" data-act="add:${p.id}" aria-label="Add ${esc(p.name)}">Add +</button>`}</div>`}</article>`}
const categories=[['milk','Dairy'],['banana','Fresh'],['bread','Bakery'],['rice','Pantry']];
function catRow(){return `<div class="category-row">${categories.map(([id,label])=>`<button class="category" data-act="category:${label}"><span class="tile">${art(id)}</span>${label}</button>`).join('')}</div>`}
function shopCard(id){const name=id==='grocer'?'Market Lane Grocers':'Neighbourhood Produce';return `<button class="shop-card" data-act="shop:${id}"><span class="shop-avatar">${ic('shop')}</span><span class="grow"><h3>${name}</h3><p>${id==='grocer'?'Groceries & everyday essentials':'Fruit & vegetables'} · Example shop</p><div class="row small mt8"><span class="accent">Open</span><span class="quiet">·</span><span class="muted">${S.located?'Est. 30–40 min':'Choose area for availability'}</span></div></span>${ic('chevron')}</button>`}
function home(){return `<button class="location-row" data-act="go:location">${ic('pin')}<span class="grow"><small class="quiet">DELIVER TO</small><b>${S.located?'Gulberg, Lahore · sample area':'Choose your delivery area'}</b></span>${ic('chevron')}</button><button class="searchbar" data-act="go:search">${ic('search')}<span>Search milk, bread, groceries…</span></button><div class="hero"><div><h2>Your daily shop.<br>Made simple.</h2><p>Everyday essentials,<br>from your local shops.</p></div><div class="hero-art">${art('milk')}${art('bread')}</div></div>${catRow()}${section('Everyday essentials','go:categories')}<div class="product-grid">${products.slice(0,4).map(p=>productCard(p)).join('')}</div>${section('Shops to explore','go:shops')}${shopCard('grocer')}${shopCard('produce')}<p class="tiny muted center mt20">Example products and prices for design review.</p>`}
function categoryScreen(){return `<h1>What’s on<br>your list?</h1><p class="muted mt8">Explore everyday essentials by category.</p><div class="two mt20">${[...categories,['detergent','Home'],['shampoo','Personal care']].map(([id,name])=>`<button class="card center" data-act="category:${name}" style="padding:10px"><div style="height:108px">${art(id,'full')}</div><b>${name}</b></button>`).join('')}</div>${section('All products','go:catalog','Browse catalogue')}<p class="small muted">Browse the catalogue even before choosing a delivery area. Select a shop to see an actual offer.</p>`}
function searchScreen(){let ps=products.filter(p=>(!S.query||p.name.toLowerCase().includes(S.query.toLowerCase()))&&(S.category==='All'||p.category===S.category));return `<div class="row"><label class="searchbar grow">${ic('search')}<input data-field="search" aria-label="Search products" value="${esc(S.query)}" placeholder="What do you need?" type="search"></label>${ib('filter','sheet:filters','Filters')}</div><div class="chips mt16">${['All','Dairy','Fresh','Bakery','Pantry'].map(c=>`<button class="chip ${S.category===c?'active':''}" data-act="filter:${c}">${c}</button>`).join('')}</div>${section(S.query?'Results for “'+esc(S.query)+'”':S.category==='All'?'Find your essentials':S.category)}<p class="small muted mb16">${ps.length} example listings · prices by shop</p><div class="product-grid">${ps.map(p=>productCard(p)).join('')}</div>${ps.length?'':empty('search','Nothing found','Try a shorter name or browse a different category.','Browse categories','go:categories')}`}
function productScreen(){const p=products.find(x=>x.id===S.selected)||products[0];return `<div class="hero-product">${art(p.id)}</div><div class="eyebrow">${p.category} · example product</div><h1 class="mt8">${p.name}</h1><p class="muted mt8">${p.unit}</p><p class="small muted mt16">${p.id==='milk'?'A daily fridge essential. Check the seller and pack size before adding.':'An everyday essential from your local shop. The image is illustrative; production uses the exact catalogue image.'}</p>${section('Choose your shop')}<button class="offer selected" data-act="offer:grocer"><span class="radio"></span><span class="grow"><b>${p.shop}</b><br><small>In stock · ${p.stock} packs listed</small></span><b>${money(p.price)}</b></button><p class="small muted mt12">Sold and delivered by the selected shop. Delivery charges are shown in your basket.</p>${section('You may also need')}<div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,2).map(x=>productCard(x)).join('')}</div>`}
function catalogScreen(){return `<h1>The everyday<br>catalogue.</h1><p class="muted mt8 mb16">Explore products, then find a shop that sells them.</p>${notice('These are catalogue products, not priced shop listings. Choose a seller before adding.') }<div class="product-grid mt16">${products.slice(0,6).map(p=>productCard(p,true)).join('')}</div>`}
function shopScreen(){const name=S.shop==='produce'?'Neighbourhood Produce':'Market Lane Grocers';return `<div class="card" style="background:var(--mint)"><span class="shop-avatar">${ic('shop')}</span><h1 class="mt12" style="font-size:25px">${name}</h1><p class="small muted mt8">Gulberg, Lahore · Example shop</p><div class="row mt12">${badge('Open')}${badge('Fee in basket','gray')}</div></div><div class="between mt12"><p class="small muted">Prepared by this shop.<br>Delivered by their own rider.</p>${link('Shop details','sheet:shop-info')}</div><label class="searchbar mt16">${ic('search')}<input data-field="shopSearch" aria-label="Search this shop" placeholder="Search this shop"></label>${section('Shop products')}<div class="product-grid">${products.filter(p=>p.merchantId===S.shop).map(p=>productCard(p)).join('')}</div>`}
function basketGroup(id){const ps=cartProducts().filter(p=>p.merchantId===id),name=ps[0]?.shop;return `<section class="card mt12"><div class="between"><div class="group-heading">${ic('shop')}<span>${name}</span></div></div><p class="tiny muted mt8">Prepared & delivered by this shop</p>${ps.map(p=>`<div class="basket-item"><div class="mini-art">${art(p.id)}</div><div class="grow"><h3>${p.name}</h3><p class="small muted">${p.unit}</p>${stepper(p.id)}</div><div style="text-align:right"><b class="price">${money(p.price*S.cart[p.id])}</b><br><button class="link small" data-act="remove:${p.id}" aria-label="Remove ${p.name}">Remove</button></div></div>`).join('')}<div class="between small mt12"><span class="muted">Shop delivery</span><b>${money(6000)}</b></div></section>`}
function summary(){const q=quote();return `<div class="summary"><div><span>Items (${totalQty()})</span><b>${money(q.sub)}</b></div><div><span>Shop deliveries (${q.groups.length})</span><b>${money(q.delivery)}</b></div><div><span>Service fee</span><b>${money(q.service)}</b></div><div class="total"><span>Total</span><b>${money(q.total)}</b></div></div>`}
function basketScreen(){if(!totalQty())return empty('basket','Your basket is empty','Find your everyday essentials. You can add products without creating an account.','Explore products','go:home');const q=quote();return `<h1>Your basket</h1><p class="small muted mt8">${totalQty()} items · ${q.groups.length} ${q.groups.length>1?'shops · separate deliveries':'shop'}</p>${q.groups.length>1?`<div class="mt16">${notice('Each shop prepares and delivers its own items. Review the delivery charges for both shops.','blue','shop')}</div>`:''}${q.groups.map(basketGroup).join('')}<div class="row-list mt16">${list('ticket','Have a promo code?','Apply a code to check eligibility','sheet:coupon')}</div><div class="card mt16">${summary()}</div><p class="small muted center mt16">No account needed to build your basket.</p>`}
function progress(stage=0){return `<div class="progress"><${stage===0?'b':'span'}>1 · Delivery</${stage===0?'b':'span'}><span class="line"></span><${stage===1?'b':'span'}>2 · Verify</${stage===1?'b':'span'}><span class="line"></span><${stage===2?'b':'span'}>3 · Review</${stage===2?'b':'span'}></div>`}
function addressFields(){return `${field('Full address','fullAddress',S.address.fullAddress,'House / apartment, street, area')}<div class="two">${field('City','city',S.address.city,'City')}${field('Contact name','name',S.address.name,'Your name')}</div>${field('Delivery instructions · optional','instructions',S.address.instructions,'Landmark, building or access details')}<div class="mt12">${link(ic('pin')+' Confirm on map','go:map')}</div>`}
function checkoutScreen(review=false){return `${progress(review?2:0)}<h1>${review?'One last check.':'Where should<br>we deliver?'}</h1><p class="small muted mt8">${review?'Review the latest items, delivery details and total.':'Add your delivery details. Sign in at the final step.'}</p>${review?`<div class="card mt20"><div class="between"><h3>Delivery address</h3>${link('Edit','go:checkout')}</div><p class="small mt8"><b>${esc(S.address.name||'Example customer')}</b><br>${esc(S.address.fullAddress||'Example Street, Gulberg')}<br>${esc(S.address.city||'Lahore')}</p><p class="small muted mt8">${esc(S.address.instructions)}</p></div>`:`<div class="card mt20"><div class="row">${ic('pin')}<h3>Delivery address</h3></div>${addressFields()}<p class="tiny muted">Your guest draft stays here during sign-in.</p></div>`}<div class="mt20"><h3>Payment</h3><button class="choice selected mt12" data-act="payment-cod"><span class="radio"></span>${ic('cash')}<span class="grow"><b>Cash on delivery</b><small>Pay when your order arrives.</small></span></button><button class="choice mt8" data-act="sheet:payment-info">${ic('card')}<span class="grow"><b>Online payment</b><small>Choose cash on delivery for now.</small></span>${badge('Not available','gray')}</button></div>${review?`<div class="card mt20"><div class="between"><h3>Items & charges</h3>${link('Edit','go:basket')}</div><div class="mt16">${summary()}</div></div>`:`<div class="summary-compact mt20"><div class="between"><span>${totalQty()} items · ${quote().groups.length} shop(s)</span><b>${money(quote().total)}</b></div><p class="tiny muted mt8">Example quote. Final fees are rechecked after sign-in.</p></div>`}<div class="form-error" id="checkoutError"></div>${review?`<p class="tiny muted mt16">Placing the order sends it to the shop. Acceptance is confirmed separately.</p>`:''}`}
function empty(icon,title,text,label,act){return `<div class="empty-content"><div class="empty-art">${ic(icon)}</div><h1>${title}</h1><p>${text}</p>${btn(label,act,'full')}<div class="mt12">${link('Back to shopping','go:home')}</div></div>`}
function locationScreen(){return `<h1>A little closer<br>to home.</h1><p class="muted mt12">Choose a delivery area to find relevant shops. You can keep browsing without sharing your location.</p><div class="mt24">${btn(ic('pin')+' Use current location','sheet:permission','full')}</div><div class="divider-or">or choose manually</div><div class="row-list">${list('pin','Lahore · Gulberg','Example area for design preview','choose-location')}${list('search','Enter another address','Use a written address and confirmed map pin','go:checkout')}</div><div class="mt20">${notice('Current location needs your permission. This preview does not access GPS.','blue')}</div>${link('Keep browsing without location','go:home')}`}
function mapScreen(){return `<h1>Pin your doorstep.</h1><p class="muted small mt8 mb16">A clear address and a confirmed pin help your shop’s rider find you.</p><div class="map-placeholder">${ic('pin')}<b>Delivery map preview</b><small>Illustrative only · not live GPS. Confirm your actual address in the app.</small></div><div class="card mt16"><h3>Delivery address</h3><p class="small muted mt8">${esc(S.address.fullAddress||'Add your house, street and area')}${S.address.city?`, ${esc(S.address.city)}`:''}</p>${link('Edit written address','go:checkout')}</div><p class="small muted mt16">Make sure the pin matches your written address. You can edit either before continuing.</p>`}
function mergedScreen(error=false){return `<div class="empty-art">${ic(error?'info':'check')}</div><h1>${error?'Your basket needs<br>a quick check.':'You’re signed in.<br>Review your basket.'}</h1><p class="muted mt12">${error?'We could not confirm whether every guest item was added to your account basket. Do not place the order yet.':'Your guest basket and any existing account items are reviewed together before ordering.'}</p><div class="card mt20"><div class="row">${ic('basket')}<h3>${totalQty()} items in this example</h3></div><p class="small muted mt12">${error?'Your delivery draft is retained. Check saved basket contents before any retry.':'Quantity, stock and prices can change during the merge. This preview has no extra account items.'}</p><div class="mt16">${summary()}</div></div><div class="mt16">${notice(error?'Your delivery details are retained. Check your saved basket before continuing.':'No order has been placed. You stay in control of the final total.',error?'warn':'','shield')}</div>`}
function sentScreen(){return `<div class="empty-art">${ic('check')}</div><div class="center"><div class="eyebrow">EXAMPLE ORDER · SB-1048</div><h1 class="mt12">Your order is<br>with the shop.</h1><p class="muted mt12">We’ll show the shop’s response here.<br>Payment is due on delivery.</p></div><div class="card mt24"><div class="group-heading">${ic('shop')} Market Lane Grocers</div><div class="row mt12">${badge('Awaiting confirmation','warn')}</div><div class="separator"></div><div class="between small"><span class="muted">Order value</span><b>${money(S.orderSnapshot?.total??77500)}</b></div><p class="small muted mt12">Example Street, Gulberg, Lahore</p></div><div class="mt16">${notice('Sent does not mean accepted. Track the confirmed status in your order.','blue')}</div>`}
function trackScreen(multi=false){return `<div class="between"><div><div class="eyebrow">EXAMPLE ORDER · SB-1048</div><h1 class="mt8">${multi?'Two shops.<br>Two deliveries.':'Your order is<br>on the way.'}</h1></div></div>${multi?`<div class="chips mt16"><button class="chip active" data-act="track-child:grocer">Groceries</button><button class="chip" data-act="track-child:produce">Fresh produce</button></div><div class="card mt12"><div class="group-heading">${ic('shop')}Neighbourhood Produce</div><div class="mt12">${badge('Preparing','warn')}</div><p class="small muted mt8">Tracked separately from your grocery delivery.</p></div>`:''}<div class="route-summary mt20"><div class="route-stop">${ic('shop')}<div><b>Market Lane Grocers</b><p class="small muted">Your shop’s rider is delivering this order.</p></div></div><div class="route-line"></div><div class="route-stop">${ic('pin')}<div><b>Example Street, Gulberg</b><p class="small muted">Your delivery address</p></div></div><p class="tiny muted mt16">Map unavailable in this preview. No live position shown.</p></div><div class="card mt12"><div class="row"><span class="avatar" style="width:40px;height:40px;border-radius:13px">AR</span><span class="grow"><b>Ali · example rider</b><p class="small muted">Assigned by Market Lane Grocers</p></span>${ib('phone','sheet:contact','Contact rider')}</div></div><div class="timeline"><div class="time-row done"><span class="time-dot"></span><div><b>Shop accepted</b><small>Your items were prepared.</small></div></div><div class="time-row current"><span class="time-dot"></span><div><b>On the way</b><small>Last confirmed delivery status.</small></div></div><div class="time-row"><span class="time-dot"></span><div><b>At your door</b><small>We’ll show the rider’s update here.</small></div></div></div><div class="customer-code"><b class="small">Your delivery code</b><div class="masked-code">••••</div><p class="tiny muted">Share with this rider only when your parcel arrives.</p></div><p class="tiny muted center mt12">Example code masked · live codes are never used in design files.</p>`}
function orderScreen(){return `<div class="between"><h1>Order SB-1048</h1></div><div class="mt12">${badge('Waiting for shop','warn')}</div><div class="card mt16"><h3>Market Lane Grocers</h3><p class="small muted mt8">Example order · 6 October 2026</p><div class="separator"></div>${(S.orderSnapshot?.items||products.slice(0,3).map(p=>({...p,quantity:1}))).map(p=>`<div class="between small mt12"><span>${p.quantity} × ${p.name}</span><b>${money(p.price*p.quantity)}</b></div>`).join('')}<div class="line-dashed"></div><div class="summary"><div><span>Items</span><b>${money(S.orderSnapshot?.sub??69500)}</b></div><div><span>Delivery</span><b>${money(S.orderSnapshot?.delivery??6000)}</b></div><div><span>Service fee</span><b>${money(S.orderSnapshot?.service??2000)}</b></div><div class="total"><span>Total</span><b>${money(S.orderSnapshot?.total??77500)}</b></div></div></div><div class="card mt16"><h3>Delivery & payment</h3><p class="small muted mt8">Example Street, Gulberg, Lahore</p><p class="small mt8">Cash on delivery · not yet collected</p></div><div class="row-list mt16">${list('route','Track this order','','go:tracking')}${list('help','Get help with this order','','go:issue')}${list('close','Cancel order','Available before the shop accepts','sheet:cancel')}</div>`}
function ordersScreen(){return `<h1>Your orders</h1><p class="muted small mt8">Track what’s coming. Review what arrived.</p><div class="chips mt16"><button class="chip active" data-act="orders-active">Active</button><button class="chip" data-act="orders-past">Past orders</button></div><button class="card full text-left mt12" data-act="go:tracking"><div class="between"><b>Market Lane Grocers</b>${badge('On the way','blue')}</div><p class="small muted mt8">SB-1048 · 3 items</p><div class="row mt12">${['milk','bread','eggs'].map(p=>`<div class="mini-art" style="width:51px;height:48px">${art(p)}</div>`).join('')}<b style="margin-left:auto">Rs 775</b></div><div class="between mt16 small"><span class="accent">Track delivery</span>${ic('arrow')}</div></button><button class="card full text-left mt12" data-act="go:multitrack"><div class="between"><b>Order from 2 shops</b>${badge('Preparing','warn')}</div><p class="small muted mt8">SB-1050 · Two separate deliveries</p><div class="mt12 small accent">View each delivery →</div></button><p class="tiny muted mt20">Fictional order history for visual review.</p>`}
function accountScreen(guest=false){return `<h1>Your account</h1>${guest?`<div class="card mt20"><span class="avatar">${ic('user')}</span><h2 class="mt16">Shop first.<br>Sign in when you’re ready.</h2><p class="small muted mt12">An account keeps your orders and addresses together. Browsing never needs one.</p><div class="mt16">${btn('Sign in or create account','auth:account','full')}</div></div>`:`<div class="card mt20 row"><span class="avatar">EC</span><div class="grow"><h3>Example customer</h3><p class="small muted">Your private shopping space</p>${link('Edit profile','sheet:profile-edit')}</div></div>`}<div class="row-list mt20">${list('bag','Your orders','Track deliveries and view past orders',guest?'auth:orders':'go:orders')}${list('pin','Saved addresses','Home, work and other delivery places',guest?'auth:addresses':'go:addresses')}${list('sun','Appearance','Light, Dark or System','go:appearance')}${list('bell','Order updates','Notifications and delivery information',guest?'auth:notifications':'go:notifications')}${list('help','Help & support','','go:help')}</div>${guest?'':`<div class="row-list mt20">${list('logout','Sign out','','sheet:signout')}${list('trash','Delete account','Review before confirming','sheet:delete-account')}</div>`}<img data-slogan class="slogan" src="${assets['sirfbazar-slogan-urdu-light.png']}" alt="بازار وہی۔ طریقہ نیا۔">`}
function addressesScreen(){return `<h1>Your places</h1><p class="small muted mt8">Keep the written address and map pin accurate.</p><div class="card mt20"><div class="between"><span class="row">${ic('home')}<b>Home</b></span>${badge('Default')}</div><p class="small mt12">Example Street, Gulberg<br>Lahore</p><div class="between mt12">${link('Edit address','go:address')}${link('Remove','sheet:remove-address')}</div></div><div class="mt16">${btn(ic('plus')+' Add a new address','new-address','secondary full')}</div>`}
function appearanceScreen(){return `<h1>Make it yours.</h1><p class="muted mt8">Choose a comfortable look for your shopping.</p><div class="stack mt24">${['light','dark','system'].map(t=>`<button class="theme-choice ${theme===t?'selected':''}" data-theme-choice="${t}" data-act="theme:${t}"><span class="mini-theme ${t}"><i></i><i></i><i></i></span><span class="grow text-left"><b>${t[0].toUpperCase()+t.slice(1)}</b><p class="small muted">${t==='system'?'Follow your device setting':t==='light'?'Bright and easy to browse':'Soft contrast for darker spaces'}</p></span><span class="radio"></span></button>`).join('')}</div><div class="card mt24"><div class="group-heading">${ic('basket')}Your basket stays with you</div><p class="small muted mt12">Changing appearance won’t reset your basket, checkout details or selected delivery.</p></div>`}
function helpScreen(){return `<h1>How can<br>we help?</h1><p class="muted mt8">Start with the order you need help with.</p><div class="row-list mt24">${list('bag','Help with an order','Missing item, delay or delivery question',S.member?'go:issue':'auth:orders')}${list('user','Account & app help','Ask a question or report a problem',S.member?'go:issue':'auth:account')}${list('history','Your support requests','Replies and the latest ticket status',S.member?'sheet:tickets':'auth:account')}</div><div class="card mt20"><h3>Buying from local shops</h3><p class="small muted mt12">Each shop prepares its own products and manages its own riders. Multi-shop baskets can arrive separately.</p><div class="separator"></div><h3>Before you place an order</h3><p class="small muted mt12">Check the seller, pack size, delivery address and final charges. You sign in only when needed.</p></div>`}
function issueScreen(){return `<h1>Tell us what<br>happened.</h1><p class="muted small mt8">Example order SB-1048</p><label class="field"><span>Issue</span><select data-field="issueCategory"><option>Missing item</option><option>Wrong item</option><option>Late delivery</option><option>Payment question</option><option>App issue</option></select></label>${field('Title','issueTitle','','A short summary')}<label class="field"><span>Details</span><textarea data-field="issueDescription" placeholder="Tell us which item or delivery needs attention."></textarea></label><div class="mt16">${notice('Your request is sent only after you submit. It does not cancel an order.','blue')}</div><p id="issueError" class="form-error"></p>`}
function replacementScreen(){return `<h1>The shop suggests<br>a replacement.</h1><p class="small muted mt8">Review before deciding. Nothing is accepted automatically.</p><div class="card mt20"><div class="eyebrow">UNAVAILABLE</div><div class="basket-item"><div class="mini-art">${art('milk')}</div><div><h3>Fresh milk · 1 litre</h3><p class="small muted">1 × Rs 290</p></div></div><div class="eyebrow mt16">PROPOSED REPLACEMENT</div><div class="basket-item"><div class="mini-art">${art('milk')}</div><div><h3>Alternative milk · 1 litre</h3><p class="small muted">1 × Rs 310</p></div></div><div class="mt12">${notice('Example difference: +Rs 20. Final order totals must be confirmed by the server.','warn')}</div></div><div class="two mt20">${btn('Decline','sheet:decline-replacement','secondary')}${btn('Accept replacement','sheet:accept-replacement','','style="font-size:12px"')}</div>`}
function ratingScreen(){return `<div class="empty-art">${ic('star')}</div><h1 class="center">How was<br>your order?</h1><p class="small muted center mt12">Market Lane Grocers · Delivered example</p><div class="stars">${[1,2,3,4,5].map(n=>`<button class="${n<=S.rating?'selected':''}" data-act="rate:${n}" aria-label="Rate ${n} stars">${ic('star')}</button>`).join('')}</div><label class="field"><span>Tell us more · optional</span><textarea data-field="reviewText" placeholder="What went well? What could improve?"></textarea></label><p class="tiny muted mt16">Reviews are optional. A review is published only after the API confirms it.</p>`}
function changesScreen(){return `<h1>A quick basket<br>update.</h1><p class="muted mt12">A price or stock level changed while you were shopping.</p><div class="card mt20"><div class="basket-item"><div class="mini-art">${art('milk')}</div><div class="grow"><h3>Fresh milk</h3><p class="small muted">Rs 290 → Rs 310</p></div>${badge('Price changed','warn')}</div><div class="basket-item"><div class="mini-art">${art('eggs')}</div><div class="grow"><h3>Farm eggs</h3><p class="small muted">Requested 2 · available 1</p></div></div></div><div class="mt16">${notice('Review these changes before placing the order. Quantities are not silently reduced.','warn')}</div>`}
function notificationsScreen(){return `<h1>Your updates</h1><p class="small muted mt8">Only updates for your customer account.</p><div class="row-list mt20">${list('route','Your order is on the way','Example · Market Lane Grocers','go:tracking')}${list('shop','The shop accepted your order','Example · SB-1048','go:order')}${list('box','Replacement needs a decision','Example · review the suggested product','go:replacement')}</div><p class="tiny muted mt16">No real notification has been sent or marked read here.</p>`}
function sceneHTML(){switch(S.view){case'home':case'nearby':return home();case'categories':return categoryScreen();case'search':return searchScreen();case'shops':return `<h1>Local shops.<br>Familiar choices.</h1><p class="muted small mt12">${S.located?'Example shops for your selected area.':'Choose an area to check which shops can deliver.'}</p><div class="chips mt20"><button class="chip active" data-act="shops-all">All shops</button><button class="chip" data-act="shop:grocer">Groceries</button><button class="chip" data-act="shop:produce">Fresh produce</button></div>${shopCard('grocer')}${shopCard('produce')}${notice('Delivery estimates require location. Actual fees appear in your basket.','blue')}`;case'shop':return shopScreen();case'product':return productScreen();case'catalog':return catalogScreen();case'basket':case'multi':return basketScreen();case'checkout':return checkoutScreen();case'review':return checkoutScreen(true);case'location':return locationScreen();case'map':return mapScreen();case'merge':return mergedScreen();case'merge-error':return mergedScreen(true);case'sent':return sentScreen();case'tracking':return trackScreen();case'multitrack':return trackScreen(true);case'order':return orderScreen();case'orders':return ordersScreen();case'guest-account':return accountScreen(true);case'account':return accountScreen();case'addresses':return addressesScreen();case'address':return `<h1>Delivery address</h1><p class="small muted mt8">Tell your shop’s rider exactly where to go.</p>${addressFields()}<label class="field"><span>Delivery contact number</span><input class="input" type="tel" data-field="phoneAddress" placeholder="+92 mobile number" value="${esc(S.address.phone)}"></label><p id="checkoutError" class="form-error"></p>`;case'appearance':return appearanceScreen();case'help':return helpScreen();case'issue':return issueScreen();case'replacement':return replacementScreen();case'rating':return ratingScreen();case'empty':return empty('basket','Your basket is empty','Browse products and add what you need. No account required.','Start shopping','go:home');case'no-service':return empty('pin','Not here just yet.','No shop was found within delivery range. Change your area, or keep exploring the catalogue.','Change area','go:location');case'no-results':return empty('search','Let’s try<br>another search.','No listings match “oat biscuits” in this example. Browse categories or try fewer words.','Search again','go:search');case'loading':return `<div class="skeleton shimmer" style="width:60%;height:20px"></div><div class="skeleton shimmer mt16" style="height:49px"></div><div class="skeleton shimmer mt16" style="height:143px"></div><div class="skeleton shimmer mt24" style="width:60%;height:20px"></div><div class="product-grid mt16">${[1,2,3,4].map(()=>'<div class="skeleton shimmer sk-block"></div>').join('')}</div><p class="small muted mt16" role="status">Loading shopping options…</p>`;case'error':return empty('wifi','Couldn’t load<br>your shops.','Check your connection and try again. Your basket has not been cleared.','Try again','retry-home');case'changes':return changesScreen();case'expired':return empty('lock','Sign in to<br>continue checkout.','Your delivery draft stays here. We’ll check your saved basket before you place anything.','Continue securely','auth:checkout');case'uncertain':return empty('clock','Let’s check before<br>trying again.','We haven’t confirmed whether your order was saved. Don’t place it a second time yet.','Check order status','check-order');case'payment':return empty('card','Payment is<br>not confirmed.','No live payment provider is connected in this reference. Don’t retry payment or place another order until the saved status is checked.','View order status','go:order');case'notifications':return notificationsScreen();default:return home()}}
function header(){const isHome=['home','nearby'].includes(S.view),top=['home','nearby','basket','multi','orders','account','guest-account','empty'].includes(S.view);const title=({basket:'Basket',multi:'Basket',orders:'Orders',account:'Account','guest-account':'Account',checkout:'Checkout',review:'Final review',tracking:'Track order',multitrack:'Track deliveries',product:'Product details',shop:'Shop',map:'Delivery pin',signin:'Checkout',verify:'Checkout'})[S.view]||scenes.find(x=>x.key===S.view)?.title.split(' · ')[0]||'SirfBazar';return `<header class="app-header">${isHome?`<img data-logo class="brand-logo" src="${assets['sirfbazar-horizontal-no-slogan-light.png']}" alt="SirfBazar">`:`<div class="row grow">${top?'':ib('back','back','Go back')}<span class="header-title">${title}</span></div>`}${isHome?ib('sun','quick-theme','Change appearance'):''}${ib(isHome?'bell':'basket',isHome?'private:notifications':'go:basket',isHome?'Order updates':'Open basket')}${!isHome&&totalQty()?`<span class="pill">${totalQty()}</span>`:''}</header>`}
function tabs(){let active=['home','nearby','loading'].includes(S.view)?'home':['basket','multi','empty'].includes(S.view)?'basket':S.view==='orders'?'orders':'account';return `<nav class="tabbar" aria-label="Main navigation">${[['home','home','Home'],['basket','basket','Basket'],['orders','bag','Orders'],['account','user','Account']].map(([key,icon,label])=>`<button class="tab ${active===key?'active':''}" data-act="tab:${key}">${ic(icon)}<span>${label}</span>${key==='basket'&&totalQty()?`<span class="count">${totalQty()}</span>`:''}</button>`).join('')}</nav>`}
function footer(){const v=S.view;let label,action;if(['home','nearby','basket','multi','orders','guest-account','account','empty','loading'].includes(v)){if(['basket','multi'].includes(v)&&totalQty()){return `<div class="dock"><div class="dock-sum"><span class="small muted">${totalQty()} items · total</span><b>${money(quote().total)}</b></div>${btn('Continue to checkout '+ic('arrow'),'go:checkout','full')}</div>`}return tabs()}if(v==='product'){label=`${S.cart[S.selected]?'Add another':'Add to basket'} · ${money(products.find(p=>p.id===S.selected).price)}`;action='add:'+S.selected}else if(v==='checkout'){label=S.member?'Review order':'Continue to sign in';action='checkout-next'}else if(v==='review'){label='Place order · '+money(quote().total);action='place'}else if(v==='map'){label='Return to delivery details';action='go:checkout'}else if(v==='merge'){label='Continue to final review';action='go:review'}else if(v==='merge-error'){label='Check saved basket';action='reconcile'}else if(v==='sent'){label='Track your order';action='go:tracking'}else if(v==='tracking'||v==='multitrack'){label='View order details';action='go:order'}else if(v==='issue'){label='Send support request';action='send-issue'}else if(v==='address'){label='Save address';action='save-address'}else if(v==='changes'){label='Review basket changes';action='go:basket'}else if(v==='rating'){label='Submit review';action='submit-rating'}else return '';return `<div class="dock">${btn(label,action,'full')}</div>`}
function render(keepScroll=false){const scroll=$('#scroller')?.scrollTop||0;$('#app-content').innerHTML=header()+`<div class="scroll" id="scroller"><main class="content" id="main-content">${sceneHTML()}</main></div>`+footer();if(keepScroll)$('#scroller').scrollTop=scroll;const current=scenes.find(x=>x.key===(S.reviewKey||S.view))||scenes[0];$('#scene-id').textContent=current.id;$('#scene-title').textContent=current.title;$('#scene-note').textContent=current.note;document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===(S.reviewKey||S.view)));$('#mobile-scenes').value=S.reviewKey||S.view;applyTheme();if(S.modal)renderModal()}
function go(key){S.history.push(S.view);S.view=key;S.reviewKey=null;S.modal=null;closeLayer();render()}
function reviewScene(key){const wanted=key;S=init();S.reviewKey=wanted;if(['basket','checkout','signin','verify','merge','review','merge-error','changes','expired','uncertain'].includes(key))seedCart();if(key==='multi')seedCart(true);if(['sent','tracking','multitrack','order','orders','account','addresses','address','notifications','issue','replacement','rating','review','merge','merge-error','payment'].includes(key))S.member=true;if(['review','merge','checkout','signin','verify','map','address','merge-error','expired'].includes(key))seedAddress();if(key==='nearby')S.located=true;S.view=['signin','verify'].includes(key)?'checkout':key;if(key==='signin'||key==='verify'){S.modal=key;S.phone='';S.code=''}if(key==='expired')S.member=false;closeLayer();render();if(S.modal)renderModal()}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
function openModal(type){previousFocus=document.activeElement;S.modal=type;renderModal();setTimeout(()=>$('#sheet')?.focus(),0)}
function closeLayer(){$('#sheet-layer').hidden=true;$('#app-content').inert=false}
function closeModal(){S.modal=null;closeLayer();if(previousFocus?.isConnected)previousFocus.focus()}
function auth(reason='checkout'){S.authReason=reason;openModal('signin')}
const googleIcon='<svg width="19" height="19" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.23c0-.71-.06-1.39-.18-2.05H12v3.88h5.38a4.6 4.6 0 0 1-2 3.02v2.51h3.23c1.89-1.74 2.99-4.3 2.99-7.36Z"/><path fill="#34A853" d="M12 22c2.7 0 4.96-.9 6.61-2.41l-3.23-2.51c-.9.6-2.05.97-3.38.97-2.61 0-4.82-1.77-5.62-4.15H3.04v2.59A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.38 13.9a6 6 0 0 1 0-3.8V7.51H3.04a10 10 0 0 0 0 8.98l3.34-2.59Z"/><path fill="#EA4335" d="M12 5.95c1.47 0 2.79.51 3.83 1.5l2.87-2.87A9.64 9.64 0 0 0 12 2a10 10 0 0 0-8.96 5.51l3.34 2.59A5.99 5.99 0 0 1 12 5.95Z"/></svg>';
function renderModal(){let title='',content='';const type=S.modal;
if(type==='signin'){title=S.authReason==='checkout'?'You’re almost there.':'Your account, simply.';content=`<p>Sign in or create an account to ${S.authReason==='checkout'?'continue checkout':'view your private information'}. Your basket stays with you.</p><label class="field"><span>Mobile number</span><div class="input-row"><b>+92</b><input class="input" data-field="authPhone" inputmode="tel" value="${esc(S.phone)}" placeholder="3xx xxxxxxx" autocomplete="tel-national"></div></label><p id="authError" class="form-error"></p><div class="mt16">${btn('Send verification code','send-code','full')}</div><div class="divider-or">or</div>${btn(googleIcon+' Continue with Google','sheet:google','secondary full')}<p class="sheet-note">New here? Verification creates your account when needed.</p><button class="sheet-close" data-act="close">Continue shopping instead</button>`}
else if(type==='verify'){title='Check your phone.';content=`<p>Enter the verification code for your mobile number. This offline preview never sends an SMS.</p><div class="between mt12"><b class="small">+92 ••• •••••••</b>${link('Change number','sheet:signin')}</div><label class="field"><span>Verification code</span><input class="input otp" data-field="authCode" inputmode="numeric" maxlength="6" value="${esc(S.code)}" placeholder="••••••" autocomplete="one-time-code"></label><p id="authError" class="form-error"></p><div class="mt16">${btn('Verify & continue','verify-code','full')}</div><div class="between mt12"><span class="small muted">Didn’t receive a code?</span>${link('Resend','resend')}</div><div class="mt16">${notice('After verification, review your basket and total. No order is placed automatically.','','shield')}</div>`}
else if(type==='filters'){title='Find the right thing.';content=`<p>Filters here affect example listings only. The live app uses supported API queries.</p><label class="field"><span>Category</span><select data-field="filterCategory">${['All','Dairy','Fresh','Bakery','Pantry'].map(c=>`<option ${S.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field"><span>Sort by</span><select data-field="sort"><option>Relevance</option><option>Price: low to high</option><option>Price: high to low</option></select></label><div class="mt20">${btn('Apply filters','apply-filters','full')}</div>`}
else if(type==='coupon'){title='Have a code?';content=`<p>Enter a promo code to check eligibility. A discount appears only after it is confirmed.</p>${field('Promo code','coupon','','Enter code')}<p id="couponError" class="form-error"></p><div class="mt16">${btn('Apply code','apply-coupon','full')}</div>`}
else if(type==='google'){title='Google sign-in';content=`<p>Google opens its account chooser in the native app. This is an offline preview of that hand-off.</p><div class="mt20">${btn('Preview successful return','google-return','full')}</div><p class="sheet-note">Design-only state. Never implement this bypass in the app.</p>`}
else if(type==='permission'){title='Find shops around you.';content=`<p>Location helps find delivery options. The real app asks the operating system for foreground access after this explanation.</p><div class="mt20">${btn('Preview area selected','preview-location','full')}</div><div class="mt12">${btn('Browse without location','deny-location','secondary full')}</div><p class="sheet-note">This reference never requests or reads GPS.</p>`}
else if(type==='payment-info'){title='Pay at your door.';content=`<p>Online payment is unavailable for this example order. You can continue with cash on delivery.</p><div class="mt16">${notice('Payment options are confirmed during checkout. Never send money through an unverified payment link.','warn')}</div><div class="mt20">${btn('Use cash on delivery','close','full')}</div>`}
else if(type==='cancel'){title='Cancel this order?';content=`<p>Cancellation is available only while the backend allows it. After shop acceptance, contact support.</p>${field('Reason · optional','cancelReason','','Tell us why')}<div class="mt20">${btn('Confirm cancellation','confirm-cancel','danger full')}</div><div class="mt12">${btn('Keep order','close','secondary full')}</div>`}
else if(type==='shop-info'){title=S.shop==='produce'?'Neighbourhood Produce':'Market Lane Grocers';content=`<p>Example shop · Gulberg, Lahore.<br>Groceries prepared and delivered by this shop.</p><div class="card mt16 small"><b>Opening hours</b><p class="muted mt8">Example: 9:00 AM–9:00 PM</p></div><p class="sheet-note">Actual times and contact details come from the shop API.</p>`}
else if(type==='contact'){title='Contact your rider';content=`<p>The native app opens the dialer with the authorized rider contact after your tap. No call is made here.</p><div class="mt20">${btn('Return to tracking','close','full')}</div>`}
else if(type==='signout'){title='Sign out?';content=`<p>Your saved orders belong to your account. Signing out does not cancel them. Private data is cleared using the existing session workflow.</p><div class="mt20">${btn('Sign out','confirm-signout','full')}</div>`}
else if(type==='delete-account'){title='Delete your account?';content=`<p>This is a destructive action. The native app must explain the actual backend retention and deletion rules before submission. Do not promise that all transaction records disappear.</p><div class="mt16">${notice('This preview does not delete an account. The live action needs explicit confirmation and verified policy.','warn')}</div><div class="mt16">${btn('Keep my account','close','full')}</div>`}
else if(type==='remove-address'){title='Remove saved address?';content=`<p>Confirm which address you are removing. Do not modify the destination of an existing order.</p><div class="mt16">${btn('Preview removal','demo-address-remove','danger full')}</div>`}
else if(type==='profile-edit'){title='Your details';content=`${field('Name','profileName','Example customer')}${field('Email · optional','profileEmail','','name@example.com','email')}<div class="mt20">${btn('Save details','save-profile','full')}</div><p class="sheet-note">Only supported customer profile fields are submitted in the native app.</p>`}
else if(type==='tickets'){title='Your support requests';content=`<p>No example support requests yet. Live requests and replies are retrieved from your account, not a general public inbox.</p><div class="mt20">${btn('Create a request','go:issue','full')}</div>`}
else if(type.includes('replacement')){title=type==='accept-replacement'?'Accept this replacement?':'Decline this replacement?';content=`<p>Your decision is sent for this order item. The order total and availability must be reloaded after confirmation.</p><div class="mt20">${btn('Confirm decision','confirm-replacement','full')}</div>`}
else{title='Preview information';content='<p>This is a local design interaction, not a live API operation.</p>'}
$('#sheet-layer').hidden=false;$('#app-content').inert=true;$('#sheet-layer').innerHTML=`<section class="sheet" id="sheet" role="dialog" aria-modal="true" aria-labelledby="sheetTitle" tabindex="-1"><div class="sheet-handle"></div>${ib('close','close','Close dialog')}<h2 id="sheetTitle">${title}</h2>${content}</section>`;applyTheme()}
function finishAuth(){S.member=true;S.code='';closeModal();if(S.authReason==='checkout'){go('merge')}else go(S.authReason==='account'?'account':S.authReason)}
function dispatch(act){const [name,arg]=act.split(':');switch(name){case'go':if(arg==='checkout'&&!totalQty()){go('empty');break}go(arg);break;case'tab':if(arg==='orders'){if(!S.member){auth('orders');break}go('orders')}else if(arg==='account')go(S.member?'account':'guest-account');else go(arg);break;case'back':closeModal();S.view=S.history.pop()||'home';S.reviewKey=null;render();break;case'add':{let p=products.find(p=>p.id===arg);if((S.cart[arg]||0)>=p.stock){toast('That is all the stock in this example.');break}S.cart[arg]=(S.cart[arg]||0)+1;render(true);toast('Added to your example basket');break}case'less':S.cart[arg]=Math.max(0,(S.cart[arg]||0)-1);render(true);break;case'remove':delete S.cart[arg];render(true);break;case'product':S.selected=arg;go('product');break;case'category':S.category=arg==='Personal care'?'Home':arg;go('search');break;case'filter':S.category=arg;render();break;case'shop':S.shop=arg;go('shop');break;case'offer':S.offer=arg;toast('This example uses the displayed merchant offer.');break;case'sheet':openModal(arg);break;case'close':closeModal();break;case'theme':applyTheme(arg);break;case'quick-theme':applyTheme(isDark()?'light':'dark');break;case'choose-location':S.located=true;go('nearby');break;case'preview-location':closeModal();S.located=true;go('nearby');toast('Example area selected · not device location');break;case'deny-location':closeModal();S.located=false;go('home');break;case'private':if(S.member)go(arg);else auth(arg);break;case'auth':auth(arg);break;case'checkout-next':if(!S.address.fullAddress.trim()||!S.address.city.trim()){$('#checkoutError').textContent='Add a written address and city to continue.';$('#scroller').scrollTop=$('#scroller').scrollHeight;break}if(S.member)go('review');else auth('checkout');break;case'send-code':if(!/^\d{10}$/.test(S.phone.replace(/\D/g,''))){$('#authError').textContent='Enter a 10-digit mobile number after +92. Use fictional details for this preview.';break}S.modal='verify';renderModal();break;case'verify-code':if(!/^\d{6}$/.test(S.code)){$('#authError').textContent='Enter six digits for this design-only verification example.';break}finishAuth();break;case'google-return':finishAuth();break;case'resend':toast('Preview only · no SMS sent. Live resend follows server cooldown.');break;case'place':if(!S.member){auth('checkout');break}S.orderPlaced=true;S.orderSnapshot={...quote(),items:cartProducts().map(p=>({...p,quantity:S.cart[p.id]}))};S.cart={};go('sent');toast('Example order recorded locally · no live order');break;case'payment-cod':toast('Cash on delivery selected');break;case'apply-filters':closeModal();render();break;case'apply-coupon':$('#couponError').textContent='This offline example cannot validate a live discount code.';break;case'reconcile':toast('Native implementation must inspect confirmed baskets before retrying a merge.');break;case'check-order':toast('Design-only status check. Live integration must find the actual saved order.');break;case'retry-home':go('home');break;case'new-address':S.address={name:'',phone:'',fullAddress:'',city:'',instructions:''};go('address');break;case'save-address':if(!S.address.fullAddress.trim()||!S.address.city.trim()){$('#checkoutError').textContent='Address and city are required.';break}go('addresses');toast('Example address saved locally');break;case'send-issue':{let desc=document.querySelector('[data-field="issueDescription"]')?.value.trim(),title=document.querySelector('[data-field="issueTitle"]')?.value.trim();if(!desc||!title){$('#issueError').textContent='Add a title and a description.';break}toast('Example request acknowledged · no message sent');go('help');break}case'rate':S.rating=+arg;render(true);break;case'submit-rating':if(!S.rating){toast('Choose a rating first.');break}toast('Example review acknowledged · not published');go('orders');break;case'confirm-signout':S.member=false;closeModal();go('guest-account');break;case'confirm-cancel':closeModal();toast('Example cancellation acknowledged · no live order changed');go('orders');break;case'confirm-replacement':closeModal();toast('Example decision recorded · no live order changed');go('order');break;case'demo-address-remove':closeModal();toast('Local preview only. Real removal must check the server result.');break;case'save-profile':closeModal();toast('Example profile saved locally');break;case'orders-active':go('orders');break;case'orders-past':go('rating');break;case'track-child':toast(arg==='grocer'?'Groceries: on the way':'Produce: preparing. Separate delivery.');break;case'shops-all':go('shops');break;case'reset':reviewScene('home');break;case'fill':seedAddress();S.phone='3000000000';S.code='654321';render(true);toast('Fictional details filled in this preview only');break}}
document.addEventListener('click',e=>{const s=e.target.closest('[data-scene]');if(s){reviewScene(s.dataset.scene);return}const a=e.target.closest('[data-act]');if(a&&!a.disabled){dispatch(a.dataset.act)}});
document.addEventListener('input',e=>{const f=e.target.dataset.field;if(!f)return;if(['fullAddress','city','name','instructions'].includes(f))S.address[f]=e.target.value;if(f==='phoneAddress')S.address.phone=e.target.value;if(f==='authPhone')S.phone=e.target.value;if(f==='authCode')S.code=e.target.value.replace(/\D/g,'').slice(0,6);if(f==='search'){S.query=e.target.value;clearTimeout(window.__searchTimer);window.__searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render(true);const el=document.querySelector('[data-field=search]');el?.focus();if(el?.type!=='search')el?.setSelectionRange(pos,pos)},220)}if(f==='shopSearch'){const val=e.target.value.toLowerCase();document.querySelectorAll('.product-card').forEach(card=>card.style.display=card.querySelector('.product-name').textContent.toLowerCase().includes(val)?'':'none')}});
document.addEventListener('change',e=>{if(e.target.id==='mobile-scenes')reviewScene(e.target.value);if(e.target.dataset.field==='filterCategory')S.category=e.target.value;if(e.target.dataset.field==='sort'){let val=e.target.value;products.sort(val==='Price: low to high'?((a,b)=>a.price-b.price):val==='Price: high to low'?((a,b)=>b.price-a.price):((a,b)=>a.id.localeCompare(b.id)))}});
document.addEventListener('keydown',e=>{if(!S.modal)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const cs=[...$('#sheet').querySelectorAll('button:not([disabled]),input,textarea,select,[tabindex="0"]')].filter(el=>el.offsetWidth||el.offsetHeight);if(!cs.length)return;if(e.shiftKey&&(document.activeElement===cs[0]||document.activeElement===$('#sheet'))){e.preventDefault();cs.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===cs.at(-1)){e.preventDefault();cs[0].focus()}}});
$('#scene-list').innerHTML=[...new Set(scenes.map(s=>s.group))].map(g=>`<div class="group-label">${g}</div>${scenes.filter(s=>s.group===g).map(s=>`<button data-scene="${s.key}"><span>${s.id}</span>${s.title}</button>`).join('')}`).join('');$('#mobile-scenes').innerHTML=scenes.map(s=>`<option value="${s.key}">${s.id} · ${s.title}</option>`).join('');
window.__customerDesign={scene:reviewScene,theme:applyTheme,dispatch,getState:()=>JSON.parse(JSON.stringify(S)),getTheme:()=>theme,scenes};
const params=new URLSearchParams(location.search);if(params.get('capture')==='1')document.documentElement.classList.add('capture');if(['light','dark','system'].includes(params.get('theme')))theme=params.get('theme');reviewScene(scenes.some(s=>s.key===params.get('screen'))?params.get('screen'):'home');applyTheme();
